// Примечание: имена компонентов Jinx UI ниже приняты по типовому набору
// (Card, Stack, Heading, Text, Badge, SegmentedControl, Slider, Switch, Divider, Select).
// Сверь их с API установленной версии @jinx-ui/react — у меня не было доступа к её документации.
import { useCallback, useState } from 'react';
import {
  Badge,
  Card,
  Divider,
  Heading,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettingsValue {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

export interface AppearanceSettingsProps {
  defaultValue?: Partial<AppearanceSettingsValue>;
  onChange?: (value: AppearanceSettingsValue) => void;
}

const DEFAULTS: AppearanceSettingsValue = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

const THEME_OPTIONS: { value: ThemeMode; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const SCALE_MIN = 80;
const SCALE_MAX = 140;

export default function AppearanceSettings({
  defaultValue,
  onChange,
}: AppearanceSettingsProps) {
  const [value, setValue] = useState<AppearanceSettingsValue>({
    ...DEFAULTS,
    ...defaultValue,
  });

  const commit = useCallback(
    (patch: Partial<AppearanceSettingsValue>) => {
      setValue((prev) => {
        const next = { ...prev, ...patch };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === value.theme)?.label ?? '';

  return (
    <Card padding="lg">
      <Stack direction="column" gap="lg">
        <Stack direction="row" align="center" justify="space-between" gap="md">
          <Heading level={2}>Внешний вид</Heading>
          <Badge tone="neutral">{themeLabel}</Badge>
        </Stack>

        <Stack direction="column" gap="xs">
          <Text as="label" id="jx-theme-label" weight="medium">
            Тема
          </Text>
          <SegmentedControl
            aria-labelledby="jx-theme-label"
            value={value.theme}
            options={THEME_OPTIONS}
            onChange={(theme: ThemeMode) => commit({ theme })}
          />
        </Stack>

        <Stack direction="column" gap="xs">
          <Stack direction="row" align="center" justify="space-between" gap="sm">
            <Text as="label" id="jx-scale-label" weight="medium">
              Масштаб интерфейса
            </Text>
            <Text tone="muted" style={{ fontVariantNumeric: 'tabular-nums' }}>
              {value.scale}%
            </Text>
          </Stack>
          <Slider
            aria-labelledby="jx-scale-label"
            min={SCALE_MIN}
            max={SCALE_MAX}
            step={1}
            value={value.scale}
            onChange={(scale: number) => commit({ scale })}
          />
          <Stack direction="row" justify="space-between" gap="sm">
            <Text size="sm" tone="muted">
              {SCALE_MIN}%
            </Text>
            <Text size="sm" tone="muted">
              {SCALE_MAX}%
            </Text>
          </Stack>
        </Stack>

        <Stack direction="row" align="center" justify="space-between" gap="md">
          <Stack direction="column" gap="none">
            <Text weight="medium">Плотная вёрстка</Text>
            <Text size="sm" tone="muted">
              Уменьшает отступы и высоту строк
            </Text>
          </Stack>
          <Switch
            aria-label="Плотная вёрстка"
            checked={value.dense}
            onChange={(dense: boolean) => commit({ dense })}
          />
        </Stack>

        <Divider />

        <Stack direction="column" gap="md">
          <Heading level={3}>Ещё</Heading>
          <Stack direction="column" gap="xs">
            <Text as="label" htmlFor="jx-font-select" weight="medium">
              Шрифт
            </Text>
            <Select
              id="jx-font-select"
              value={value.font}
              options={FONT_OPTIONS}
              onChange={(font: FontFamily) => commit({ font })}
            />
          </Stack>
        </Stack>
      </Stack>
    </Card>
  );
}

